    return createWorkflow<INPUT_SCHEMA, RESULT_SCHEMA, SUSPEND_SCHEMA, RESUME_SCHEMA>(
      this.config,
      // @ts-expect-error - upstream types work and this is nature of how the createWorkflow function is typed using variadic args
      ...this.steps,
