    OS extends z.ZodTypeAny,
    SS extends z.ZodTypeAny = z.ZodTypeAny,
    RS extends z.ZodTypeAny = z.ZodTypeAny,
  >(
    config: WorkflowStepConditionalWhenConfig<
      WorkflowInput<INPUT_SCHEMA>,
