    INPUT_SCHEMA,
    RESULT_SCHEMA,
    NEW_DATA | CURRENT_DATA,
    SUSPEND_SCHEMA,
    RESUME_SCHEMA
  >;

  andWhen(config: any): any {
    const finalStep = andWhen(config) as WorkflowStep<WorkflowInput<INPUT_SCHEMA>, any, any>;
    this.steps.push(finalStep);
    // Return type is handled by overloads
    return this as any;
  }

  /**
